    "questionZh": "注意：該問題包含在許多描述相同設定的問題中。然而，每個問題都有一個\n獨特的結果。確定解決方案是否符合要求。\n您公司的 Active Directory 林包含數千個使用者帳戶。\n您已獲悉所有網路資源將會遷移到 Azure。此後，本地資料中心將\n退休了。\n一旦計劃的遷移完成，您需要採用一種策略來減少對使用者的影響。\n解決方案：您計劃需要 Azure 多重驗證 (MFA)。\n解決方案是否達到目標？",
