    "questionZh": "注意：此問題是呈現相同場景的一系列問題的一部分。該系列中的每個問題都包含一個\n可能實現既定目標的獨特解決方案。有些問題集可能有多個正確答案，而其他問題集可能有多個正確答案\n可能沒有正確的解決方案。\n回答本部分的問題後，您將無法返回該部分。這樣一來，這些問題就不會出現在\n評論畫面。\n貴公司計劃將其所有資料和資源遷移到 Azure。\n該公司的遷移計畫規定，Azure 中只能使用平台即服務 (PaaS) 解決方案。\n您需要部署符合公司遷移計畫的Azure環境。\n解決方案：建立 Azure 應用程式服務和 Azure 儲存體帳戶。\n這達到目標了嗎？",
    "answerTextZh": "B"
