    "questionZh": "您有一個包含 100 台伺服器的本機網路。\n您需要推薦一個為用戶提供額外資源的解決方案。此解決方案必須最大限度地減少資本和\n營運支出成本。\n您應該在建議中包含哪些內容？",
    "answerTextZh": "D"
