    "answerTextZh": "第 1 欄：否 -\n公司並不總是必須從內部網路遷移來實施混合雲。\n你可以從\n公有雲，然後將其與本地基礎設施結合以實施混合雲。\n框 2：是 -\n企業可以利用公有雲來擴展內部網路的運算資源。\n這很常見。\n當\n您需要更多資源，而不是支付新的本地基礎設施費用，您可以配置雲端環境並\n使用 VPN 將本地網路連接到雲端環境。\n第 3 欄：否 -\n並非只有訪客使用者才能存取雲端資源。\n您可以向任何擁有 Azure Active 帳戶的人提供\n對雲端資源的目錄存取。\n身份驗證方案有很多種，但常見的一種方案是將本機 Active Directory 帳戶複製到\nAzure Active Directory 並提供對 Azure Active Directory 帳戶的存取。\n另一種常用的身份驗證\n方法是“聯合”，其中存取雲端資源的身份驗證傳遞給另一個身份驗證提供程序，例如\n作為本機 Active Directory。\n參考："
