    "questionZh": "您的公司有一個包含多台伺服器的本機網路。\n公司計劃減少以下行政職責：\n- 備份應用程式數據\n- 更換故障的伺服器硬體\n- 管理實體伺服器安全\n- 更新伺服器作業系統\n- 管理共用文件的權限\n該公司計劃將伺服器遷移到Azure虛擬機器。\n您需要確定計劃遷移後將消除哪些管理職責。\n您應該確定哪兩項責任？每個正確答案都代表一個完整的解決方案。\n注意：每個正確的選擇都值得一分。",
    "answerTextZh": "AC"
