    "answerText": "Box 1: No -\nBuilding a data center infrastructure is capital expenditure, not operation expenditure.\nBox 2: Yes -\nOpEx is ongoing costs (costs of operations) such as staff salaries.\n\nOpEx is ongoing costs (costs of operations) such as staff salaries.\nBox 2: Yes -\nOpEx is ongoing costs (costs of operations) such as leasing software.\nIf you purchased software as a one-off purchase, that\nwould be CapEx, but leasing software is ongoing so it's OpEx.",
