    "answerTextZh": "第 1 欄：否 -\n建設資料中心基礎設施是資本支出，而不是營運支出。\n框 2：是 -\n營運支出是持續成本（營運成本），例如員工薪資。\n\n營運支出是持續成本（營運成本），例如員工薪資。\n框 2：是 -\n營運支出是持續成本（營運成本），例如租賃軟體。\n如果您一次性購買軟體，那麼\n是資本支出，但租賃軟體正在進行中，因此是營運支出。"
