    "options": [],
    "answer": [],
    "answerText": "Box 1: No -\nYou can assign service administrators and co-administrators in the Azure Portal but there can only be one account\nadministrator.\nBox 2: No -\nYou need an Azure Active Directory account to manage a subscription, not a Microsoft account.\nAn account is created in the Azure Active Directory when you create the subscription.\nFurther accounts can be created in the\nAzure Active Directory to manage the subscription.\nBox 3: No -\n\nBox 3: No -\nResource groups are logical containers for Azure resources.\nHowever, resource groups do not contain subscriptions.\nSubscriptions contain resource groups.\n\nofferings",
    "comments": "",
