    "questionZh": "熱點 -\n對於以下每個陳述，如果該陳述為真，請選擇「是」。否則，選擇否。\n注意：每個正確的選擇都值得一分。\n熱門區域：",
    "answerTextZh": "第 1 欄：否 -\n您可以在 Azure 入口網站中指派服務管理員和共同管理員，但只能有一個帳戶\n管理員。\n第 2 欄：否 -\n您需要 Azure Active Directory 帳戶來管理訂閱，而不是 Microsoft 帳戶。\n建立訂閱時，會在 Azure Active Directory 中建立帳戶。\n可以在以下位置建立更多帳戶\n用於管理訂閱的 Azure Active Directory。\n第 3 欄：否 -\n\n第 3 欄：否 -\n資源組是 Azure 資源的邏輯容器。\n但是，資源組不包含訂閱。\n訂閱包含資源組。\n參考：\n\n供品"
