    "question": "HOTSPOT -\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNOTE: Each correct selection is worth one point.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "Box 1: No -\nNot all Azure regions support availability zones.\nBox 2: No -\nAvailability zones can be used with many Azure services, not just VMs.\nBox 3: No -\n\nBox 3: No -\nAvailability Zones are unique physical locations within a single Azure region.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n對於以下每個陳述，如果該陳述為真，請選擇「是」。否則，選擇否。\n注意：每個正確的選擇都值得一分。\n熱門區域：",
    "answerTextZh": "第 1 欄：否 -\n並非所有 Azure 區域都支援可用區。\n第 2 欄：否 -\n可用區可與許多 Azure 服務一起使用，而不僅僅是 VM。\n第 3 欄：否 -\n\n第 3 欄：否 -\n可用區是單一 Azure 區域內的唯一實體位置。\n參考："
