    "answerText": "Availability Zones is a high-availability offering that protects your applications and data from datacenter failures. Availability\nZones are unique physical locations within an Azure region.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n要完成句子，請在答案區中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "可用區是一種高可用性產品，可保護您的應用程式和資料免受資料中心故障的影響。可用性\n區域是 Azure 區域內的唯一實體位置。\n參考："
