    "question": "Note: This question is part of a series of questions that present the same scenario. Each question in the series contains a\nunique solution that might meet the stated goals. Some question sets might have more than one correct solution, while others\nmight not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these questions will not appear in\nthe review screen.\nYou plan to deploy several Azure virtual machines.\nYou need to ensure that the services running on the virtual machines are available if a single data center fails.\nSolution: You deploy the virtual machines to two or more scale sets.\nDoes this meet the goal?",
