    "questionZh": "注意：此問題是呈現相同場景的一系列問題的一部分。該系列中的每個問題都包含一個\n可能實現既定目標的獨特解決方案。有些問題集可能有多個正確答案，而其他問題集可能有多個正確答案\n可能沒有正確的解決方案。\n回答本部分的問題後，您將無法返回該部分。這樣一來，這些問題就不會出現在\n評論畫面。\n您計劃部署多個 Azure 虛擬機器。\n您需要確保在單一資料中心發生故障時，虛擬機器上執行的服務可用。\n解決方案：將虛擬機器部署到兩個或更多規模集。\n這達到目標了嗎？",
