    "answerText": "Box 1: Azure Functions -\nAzure Functions allows you to implement your system's logic into readily available blocks of code called \"functions\".\nDifferent functions can run anytime you need to respond to critical events.\n\nBox 2: Azure Functions -\nAzure Logic Apps can have multiple stateful and stateless workflows.\nBox 3: Azure Logic Apps -\nAzure Logic Apps is a cloud-based platform for creating and running automated workflows that integrate your apps, data,\nservices, and systems.\n\nfunctions/functions-overview",
