    "id": 141,
    "topic": 1,
    "type": "hotspot",
    "question": "HOTSPOT -\nTo answer, select the appropriate option in the answer area.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "Box: The virtual machines can be moved to the new subscription.\nYou can move a VM and its associated resources to a different subscription by using the Azure portal.\nNote: Repeat the process below for each Resource Group containing the VMs.\n1. Go to the Azure portal to manage the resource group containing the VM to move. Search for and select Resource groups.\n2. Choose the resource group containing the VM that you would like to move.\n3. At the top of the page for the resource group, select Move and then select Move to another subscription. The Move\nresources page opens.\n4. Select each of the resources to move. In most cases, you should move all of the related resources that are listed.\n5. Select the Subscription where you want the VM to be moved.\n6. Select an existing Resource group, or enter a name to have a new resource group created.\n7. When you are done, select that you understand that new resource IDs will be created and that the new IDs will need to be\nused with the VM after it is moved, and then select OK.\n\nused with the VM after it is moved, and then select OK.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n要回答，請在答案區域中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "Box：虛擬機器可以移動到新的訂閱。\n可以使用 Azure 入口網站將 VM 及其關聯資源移至不同的訂閱。\n注意：對包含 VM 的每個資源組重複下列程序。\n1. 前往 Azure 入口網站管理包含要移動的 VM 的資源群組。搜尋並選擇資源組。\n2. 選擇包含要移動的虛擬機器的資源群組。\n3. 在資源組頁面的頂部，選擇“移動”，然後選擇“移動到另一個訂閱”。搬遷\n資源頁面開啟。\n4. 選擇要移動的每個資源。在大多數情況下，您應該移動列出的所有相關資源。\n5. 選擇要將虛擬機器移至的訂閱。\n6. 選擇現有資源組，或輸入名稱以建立新資源組。\n7. 完成後，選擇您了解將建立新的資源 ID，並且需要將新的 ID 設定為\n移動後與虛擬機器一起使用，然後選擇“確定”。\n\n移動後與虛擬機器一起使用，然後選擇“確定”。\n參考："
