    "answerText": "Box 1: Platform as a service (PaaS)\nAzure App Service is a fully managed platform for building web applications.\nPlatform as a service (PaaS) is a complete development and deployment environment in the cloud, with resources that\nenable you to deliver everything from simple cloud-based apps to sophisticated, cloud-enabled enterprise applications.\nBox 2: Infrastructure as a service (IaaS)\nWindows Azure Virtual Machines, an Infrastructure-as-a-Service (IaaS) offering in Windows Azure, was released back in 2012.\nBox 3: Software as a service (SaaS)\nDynamics 365 is a set of interconnected, modular Software-as-a-Service (SaaS) applications and services designed to both\ntransform and enable your core customers, employees, and business activities.\n\ntransform and enable your core customers, employees, and business activities.",
    "comments": "",
