    "questionZh": "拖放 -\n將雲端服務模型與適當的產品相匹配。\n要回答，請將適當的型號從左側列拖曳到右側的產品中。每個型號只能使用一次，\n不只一次，或者根本沒有。\n注意：每場正確的比賽都值得一分。\n選擇並放置：",
    "answerTextZh": "專欄 1：平台即服務 (PaaS)\nAzure 應用程式服務是用於建立 Web 應用程式的完全託管平台。\n平台即服務 (PaaS) 是雲端中完整的開發和部署環境，擁有以下資源：\n使您能夠交付從簡單的基於雲端的應用程式到複雜的、支援雲端的企業應用程式的一切。\n框 2：基礎設施即服務 (IaaS)\nWindows Azure 虛擬機器是 Windows Azure 中的基礎架構即服務 (IaaS) 產品，於 2012 年發布。\n專欄 3：軟體即服務 (SaaS)\nDynamics 365 是一組互連的模組化軟體即服務 (SaaS) 應用程式和服務，旨在\n轉變並支持您的核心客戶、員工和業務活動。\n\n轉變並支持您的核心客戶、員工和業務活動。\n參考："
