    "questionZh": "拖放 -\n將雲端服務模型與適當的解決方案相匹配。\n要回答，請將對應的雲端服務模型從左側列拖曳到右側的解決方案 每個雲端服務\n模型可以使用一次、多次或完全不使用。\n注意：每場正確的比賽都值得一分。\n選擇並放置：",
    "answerTextZh": "框 1：基礎設施即服務 (IaaS)\nAzure 檔案是一種簡單、安全、無伺服器的企業級雲端檔案共用。\n基礎設施即服務 (IaaS) 是一種雲端運算服務，提供基本的運算、儲存和網絡\n按需提供資源，按使用量付費。\n框 2：軟體即服務 (SaaS)\nDynamics 365 是一組互連的模組化軟體即服務 (SaaS) 應用程式和服務，旨在\n轉變並支持您的核心客戶、員工和業務活動。它包括 Dynamics 365 Finance：使用\n指導性的、基於規則的會計科目表和無代碼配置服務，以簡化監管報告、電子發票、\n和全球支付。\n框 3：平台即服務 (PaaS)\n平台即服務 (PaaS) 是雲端中完整的開發和部署環境，擁有以下資源：\n\n平台即服務 (PaaS) 是雲端中完整的開發和部署環境，擁有以下資源：\n使您能夠交付從簡單的基於雲端的應用程式到複雜的、支援雲端的企業應用程式的一切。\n參考："
