    "answerText": "A resource group is a logical container for Azure resources.\nResource groups make the management of Azure resources\neasier.\nWith a resource group, you can allow a user to manage all resources in the resource group, such as virtual machines,\nwebsites, and subnets.\nThe permissions you apply to the resource group apply to all resources contained in the resource\ngroup.",
