    "answerText": "The term compute refers to the hosting model for the computing resources that your application runs on. For Azure this\ninclude:\nAzure Container Instances. The fastest and simplest way to run a container in Azure, without having to provision any virtual\nmachines and without having to adopt a higher-level service.\nNote, and also the following:\nAzure App Service. A managed service for hosting web apps, mobile app back ends, RESTful APIs, or automated business\nprocesses.\nAzure Spring Cloud. A managed service designed and optimized for hosting Spring Boot apps.\nAzure Kubernetes Service (AKS). A managed Kubernetes service for running containerized applications.\nAzure Batch. A managed service for running large-scale parallel and high-performance computing (HPC) applications\nAzure Functions. A managed FaaS service.\nAzure Service Fabric. A distributed systems platform that can run in many environments, including Azure or on premises.\nAzure Virtual machines. Deploy and manage VMs inside an Azure virtual network.\nAzure Container Apps. Deploy and manage VMs inside an Azure virtual network.\n\nAzure Container Apps. Deploy and manage VMs inside an Azure virtual network.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n選出正確完成句子的答案。\n熱門區域：",
    "answerTextZh": "術語「計算」是指應用程式運行所在的運算資源的託管模型。對於 Azure 這個\n包括：\nAzure 容器執行個體。在 Azure 中執行容器的最快、最簡單的方法，無需預配任何虛擬\n機器，而無需採用更高等級的服務。\n請注意，還有以下內容：\nAzure 應用程式服務。用於託管 Web 應用程式、行動應用程式後端、RESTful API 或自動化業務的託管服務\n流程。\n蔚藍春雲。專為託管 Spring Boot 應用程式而設計和最佳化的託管服務。\nAzure Kubernetes 服務 (AKS)。用於執行容器化應用程式的託管 Kubernetes 服務。\n天青批次。用於運行大規模平行和高效能運算 (HPC) 應用程式的託管服務\nAzure 函數。託管 FaaS 服務。\nAzure 服務結構。一個分散式系統平台，可以在許多環境中執行，包括 Azure 或本機。\nAzure 虛擬機器。在 Azure 虛擬網路內部署和管理 VM。\nAzure 容器應用程式。在 Azure 虛擬網路內部署和管理 VM。\n\nAzure 容器應用程式。在 Azure 虛擬網路內部署和管理 VM。\n參考："
