    "answerText": "Box 1: No -\nA resource can interact with resources in other resource groups.\nBox 2: Yes -\nDeleting the resource group will remove the resource group as well as all the resources in that resource group.\nThis can be\nuseful for the management of resources.\nFor example, a virtual machine has several components (the VM itself, virtual disks,\nnetwork adapter etc.).\nBy placing the VM in its own resource group, you can delete the VM along with all its associated\ncomponents by deleting the resource group.\nAnother example is when creating a test environment.\nYou could place the entire test environment (Network components,\nvirtual machines etc.) in one resource group.\nYou can then delete the entire test environment by deleting the resource\ngroup.\n\ngroup.\nBox 3: Yes -\nResources from multiple different regions can be placed in a resource group.\nThe resource group only contains metadata\nabout the resources it contains.",
