    "answerTextZh": "第 1 欄：否 -\n資源可以與其他資源組中的資源互動。\n框 2：是 -\n刪除資源組將刪除該資源組以及該資源組中的所有資源。\n這可以是\n對於資源管理很有用。\n例如，虛擬機器有多個元件（VM 本身、虛擬磁碟、\n網路適配器等）。\n透過將虛擬機器放置在自己的資源群組中，您可以刪除該虛擬機器及其所有關聯的資源群組。\n透過刪除資源組來取得組件。\n另一個例子是建立測試環境時。\n您可以放置整個測試環境（網路元件、\n虛擬機器等）位於一個資源群組中。\n然後，您可以透過刪除資源來刪除整個測試環境\n組。\n\n團體。\n框 3：是 -\n多個不同區域的資源可以放在一個資源群組。\n資源組僅包含元數據\n關於它所包含的資源。\n參考文獻：\n\n effective-ways-to-delete-resources-in-a-resource-group-on-azure/"
