    "answerText": "Box 1: Yes -\nAzure Service Health consists of three components: Azure Status, Azure Service Heath and Azure Resource Health.\nAzure service health provides a personalized view of the health of the Azure services and regions you're using. This is the\nbest place to look for service impacting communications about outages, planned maintenance activities, and other health\nadvisories because the authenticated Azure Service Health experience knows which services and resources you currently\nuse.\nTo view the health of all other services available in Azure, you would use the Azure Status component of Azure Service\nHealth.\nAzure status informs you of service outages in Azure on the Azure Status page. The page is a global view of the\nhealth of all Azure services across all Azure regions.\n\nhealth of all Azure services across all Azure regions.\nBox 2: Yes -\nThe best way to use Service Health is to set up Service Health alerts to notify you via your preferred communication\nchannels when service issues, planned maintenance, or other changes may affect the Azure services and regions you use.\nBox 3: No -\nYou can use Resource Health to view the health of a virtual machine.\nHowever, you cannot use Resource Health to prevent a\nservice failure affecting the virtual machine.\nAzure resource health provides information about the health of your individual cloud resources such as a specific virtual\nmachine instance.",
    "comments": "",
    "references": [],
