    "answerTextZh": "第 1 欄：是 -\nAzure 服務運作狀況由三個元件組成：Azure 狀態、Azure 服務運作狀況和 Azure 資源運作狀況。\nAzure 服務運作狀況提供您正在使用的 Azure 服務和區域的運作狀況的個人化視圖。這是\n尋找影響有關中斷、計劃維護活動和其他健康狀況的通訊的服務的最佳位置\n建議，因為經過驗證的 Azure 服務運作狀況體驗知道您目前使用哪些服務和資源\n使用。\n若要查看 Azure 中所有其他可用服務的運作狀況，您可以使用 Azure 服務的 Azure 狀態元件\n健康。\nAzure 狀態會在 Azure 狀態頁面上通知你 Azure 中的服務中斷。該頁面是全域視圖\n所有 Azure 區域中所有 Azure 服務的運作狀況。\n\n所有 Azure 區域中所有 Azure 服務的運作狀況。\n框 2：是 -\n使用服務運作狀況的最佳方法是設定服務運作狀況警報，透過您的首選通訊方式通知您\n服務問題、計劃維護或其他變更可能會影響您使用的 Azure 服務和區域時的管道。\n第 3 欄：否 -\n您可以使用資源運作狀況來查看虛擬機器的運作狀況。\n但是，您不能使用資源運作狀況來阻止\n影響虛擬機器的服務故障。\nAzure 資源運作狀況提供有關單一雲端資源（例如特定虛擬資源）運作狀況的信息\n機器實例。\n參考文獻："
