    "questionZh": "您有一個 Azure 環境。\n您需要從執行 Android 作業系統的平板電腦建立新的 Azure 虛擬機器。\n三種可能的解決方案是什麼？每個正確答案都代表一個完整的解決方案。\n注意：每個正確的選擇都值得一分。",
