    "answerText": "Azure Resource Manager templates provides a common platform for deploying objects to a cloud infrastructure and for\nimplementing consistency across the\nAzure environment.\nAzure policies are used to define rules for what can be deployed and how it should be deployed. Whilst this can help in\nensuring consistency, Azure policies do not provide the common platform for deploying objects to a cloud infrastructure.",
    "comments": "",
