    "questionZh": "熱點 -\n要完成句子，請在答案區中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "Azure資源管理器範本提供了一個通用平臺，用於將物件部署到雲端基礎結構，並\n在整個系統中實現一致性\nAzure環境。\nAzure原則用於定義可部署的內容以及應如何部署的規則。 雖然這可以幫助\n確保一致性， Azure原則不提供將物件部署到雲端基礎結構的通用平臺。"
