    "questionZh": "注意：此題屬於一系列使用相同案例的題組。每題會提供一個可能符合目標的獨特解決方案；有些題組可能有多個正確解，有些則可能沒有正確解。\n在此區段作答後將無法返回上一題，因此這些題目不會出現在複查畫面中。\nAn Azure administrator plans to run a PowerShell script that creates Azure resources.\n你需要 recommend which computer configuration to use to run the script.\n解決方案： Run the script from a computer that runs Windows 10 and has the Azure PowerShell module installed.\n這是否符合目標？",
