    "answerTextZh": "框1 ：是-\n框2 ：否-\n可透過\n在Azure入口網站的雲端服務區域中，您可以：\n更新服務角色或部署。\n將分階段部署推廣到生產環境。\n\n將資源連結到您的雲端服務，以便您可以查看資源相依性並一起擴展資源。\n刪除雲端服務或部署。\n框3 ：是-"
