    "id": 203,
    "topic": 1,
    "type": "single",
    "question": "A team of developers at your company plans to deploy, and then remove, 50 customized virtual machines each week. Thirty of\nthe virtual machines run Windows\nServer 2016 and 20 of the virtual machines run Ubuntu Linux.\nYou need to recommend which Azure service will minimize the administrative effort required to deploy and remove the virtual\nmachines.\nWhat should you recommend?",
