    "question": "HOTSPOT -\nSelect the answer that correctly completes the sentence.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "Microsoft 365 compliance is now called Microsoft Purview and the solutions within the compliance area have been\nrebranded.\nWhen you first visit the compliance portal, the card section on the home page shows you at a glance how your organization\nis doing with data compliance, what solutions are available for your organization, and a summary of any active alerts.\nFrom here, you can:\n* Review the Microsoft Purview Compliance Manager card, which leads you to the Compliance Manager solution. Compliance\nManager helps simplify the way you manage compliance.\n* Review the new Solution catalog card, which links to collections of integrated solutions you can use to help you manage\nend-to-end compliance scenarios. A solution's capabilities and tools might include a combination of policies, alerts, reports,\nand more.\n* Review the Active alerts card, which includes a summary of the most active alerts and includes a link where you can view\nmore detailed information, such as\nSeverity, Status, Category, and more.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n選出正確完成句子的答案。\n熱門區域：",
    "answerTextZh": "Microsoft 365 compliance is now called Microsoft Purview and the solutions within the compliance area have been\nrebranded.\nWhen you first visit the compliance portal, the card section on the home page shows you at a glance how your organization\nis doing with data compliance, what solutions are available for your organization, and a summary of any active alerts.\nFrom here, you can:\n* Review the Microsoft Purview Compliance Manager card, which leads you to the Compliance Manager solution. Compliance\nManager helps simplify the way you manage compliance.\n* Review the new Solution catalog card, which links to collections of integrated solutions you can use to help you manage\nend-to-end compliance scenarios. A solution's capabilities and tools might include a combination of policies, alerts, reports,\nand more.\n* Review the Active alerts card, which includes a summary of the most active alerts and includes a link where you can view\nmore detailed information, such as\nSeverity, Status, Category, and more.\n參考資料:"
