    "answerTextZh": "Box 1: 是 -\n\nAzure Monitor maximizes the availability and performance of your applications and services by delivering a comprehensive\nsolution for collecting, analyzing, and acting on telemetry from your cloud and on-premises environments.\nBox 2: 是 -\nAlerts in Azure Monitor proactively notify you of critical conditions and potentially attempt to take corrective action.\nBox 3: 是 -\nAzure Monitor uses Target Resource, which is the scope and signals available for alerting. A target can be any Azure\nresource. Example targets: a 虛擬機器, a storage account, a 虛擬機器 scale set, a Log Analytics workspace, or\nan Application Insights resource.\n參考資料:\n \nmonitor/platform/alerts-overview"
