    "answerText": "You can access Azure Cloud Shell in the Azure portal by clicking the icon.\nAzure Cloud Shell is an interactive, authenticated, browser-accessible shell for managing Azure resources. It provides the\nflexibility of choosing the shell experience that best suits the way you work, either Bash or PowerShell.\nCloud Shell enables access to a browser-based command-line experience built with Azure management tasks in mind.",
