    "questionZh": "您有一臺名為VM1的虛擬機器執行Windows Server 2016。 VM1位於美國東部Azure區域。\n您應該從Azure入口網站使用哪個Azure服務來檢視服務失敗通知，這可能會影響\nVM1?",
