    "question": "DRAG DROP -\nMatch the Azure Services service to the correct descriptions.\nInstructions: To answer, drag the appropriate service from the column on the left to its description on the right. Each service\nmay be used once, more than once, or not at all.\nNOTE: Each correct match is worth one point.\nSelect and Place:",
    "options": [],
