    "question": "DRAG DROP -\nMatch the Azure services benefits to the correct descriptions.\nInstructions: To answer, drag the appropriate benefit from the column on the left to its description on the right. Each benefit\nmay be used once, more than once, or not at all.\nNOTE: Each correct match is worth one point.\nSelect and Place:",
    "options": [],
    "answer": [],
    "answerText": "Correct Answer:\n\nBox 1: Microsoft Sentinel -\nMicrosoft Sentinel is a scalable, cloud-native, security information and event management (SIEM) and security orchestration,\nautomation, and response (SOAR) solution. Microsoft Sentinel delivers intelligent security analytics and threat intelligence\nacross the enterprise, providing a single solution for attack detection, threat visibility, proactive hunting, and threat\nresponse.\nBox 2: Microsoft Defender for Cloud\nYou can find your overall secure score, as well as your score per subscription, through the Azure portal. Defender for Cloud\ndisplays your secure score prominently in the portal.\nBox 3: Azure Key Vault -\nA favored approach to store the credentials or keys in the Azure Key Vault as secrets and reference the secrets as\nenvironment variables in our Azure functions apps.",
    "comments": "",
