    "answerTextZh": "Box 1:\nTo monitor threats by using sensors, you would use Azure Advanced Threat Protection (ATP).\n\nTo monitor threats by using sensors, you would use Azure Advanced Threat Protection (ATP).\nAzure Advanced Threat Protection (ATP) is a cloud-based security solution that leverages your on-premises Active Directory\nsignals to identify, detect, and investigate advanced threats, compromised identities, and malicious insider actions directed\nat your organization.\nSensors are software packages you install on your servers to upload information to Azure ATP.\nBox 2:\nTo enforce MFA based on a condition, you would use Azure Active Directory Identity Protection.\nAzure AD Identity Protection helps you manage the roll-out of Azure Multi-Factor Authentication (MFA) registration by\nconfiguring a Conditional Access policy to require MFA registration no matter what modern authentication app you are\nsigning in to.\n參考資料:\n \nus/azure/active-directory/identity-protection/howto-identity-protection-configure-mfa-policy"
