    "answer": [],
    "answerText": "Azure Information Protection is used to automatically add a watermark to Microsoft Word documents that contain credit card\ninformation.\nYou use Azure Information Protection labels to apply classification to documents and emails. When you do this, the\nclassification is identifiable regardless of where the data is stored or with whom it's shared. The labels can include visual\nmarkings such as a header, footer, or watermark.\nLabels can be applied automatically by administrators who define rules and conditions, manually by users, or a combination\nwhere users are given recommendations.\nIn this question, we would configure a label to be automatically applied to\nMicrosoft Word documents that contain credit card information. The label would then add the watermark to the documents.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n要完成句子，請在答案區中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "Azure Information Protection is used to automatically add a watermark to Microsoft Word documents that contain credit card\ninformation.\nYou use Azure Information Protection labels to apply classification to documents and emails. When you do this, the\nclassification is identifiable regardless of where the data is stored or with whom it's shared. The labels can include visual\nmarkings such as a header, footer, or watermark.\nLabels can be applied automatically by administrators who define rules and conditions, manually by users, or a combination\nwhere users are given recommendations.\nIn this question, we would configure a label to be automatically applied to\nMicrosoft Word documents that contain credit card information. The label would then add the watermark to the documents.\n參考資料:\n\n參考資料:"
