    "answerText": "CD\nAzure Government is a cloud environment specifically built to meet compliance and security requirements for US\ngovernment. This mission-critical cloud delivers breakthrough innovation to U.S. government customers and their partners.\nAzure Government applies to government at any level\nג\nfrom state and local governments to federal agencies including\nDepartment of Defense agencies.\nThe key difference between Microsoft Azure and Microsoft Azure Government is that Azure Government is a sovereign cloud.\nIt's a physically separated instance of Azure, dedicated to U.S. government workloads only. It's built exclusively for\ngovernment agencies and their solution providers.",
