    "options": [],
    "answer": [],
    "answerText": "Box 1: No -\nIt is not true that you must deploy a federation solution or sync on-premises identities to the cloud. You can have a cloud-\nonly environment and use MFA.\n\nBox 2: No -\nPicture identification and passport numbers are not valid MFA authentication methods. Valid methods include: Password,\nMicrosoft Authenticator App, SMS and\nVoice call.\nBox 3:\nYou can configure MFA to be required for administrator accounts only or you can configure MFA for any user account.",
    "comments": "",
