    "options": [],
    "answer": [],
    "answerText": "Box 1: Yes -\nYou can send Azure AD activity logs to Azure Monitor logs to enable rich visualizations, monitoring and alerting on the\nconnected data.\nAll data collected by Azure Monitor fits into one of two fundamental types, metrics and logs (including Azure AD activity\nlogs). Activity logs record when resources are created or modified. Metrics tell you how the resource is performing and the\nresources that it's consuming.\n\nresources that it's consuming.\nBox 2: Yes -\nAzure Monitor can consolidate log entries from multiple Azure resources, subscriptions, and tenants into one location for\nanalysis together.\nBox 3: Yes -\nYou can create alerts in Azure Monitor.\nAlerts in Azure Monitor proactively notify you of critical conditions and potentially attempt to take corrective action. Alert\nrules based on metrics provide near real time alerting based on numeric values, while rules based on logs allow for complex\nlogic across data from multiple sources.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n對於以下每個陳述，如果該陳述為真，請選擇「是」。否則，選擇否。\n注意：每個正確的選擇都值得一分。\n熱門區域：",
    "answerTextZh": "Box 1: 是 -\nYou can send Azure AD activity logs to Azure Monitor logs to enable rich visualizations, monitoring and alerting on the\nconnected data.\nAll data collected by Azure Monitor fits into one of two fundamental types, metrics and logs (including Azure AD activity\nlogs). Activity logs record when resources are created or modified. Metrics tell you how the resource is performing and the\nresources that it's consuming.\n\nresources that it's consuming.\nBox 2: 是 -\nAzure Monitor can consolidate log entries from multiple Azure resources, 訂用帳戶s, and tenants into one location for\nanalysis together.\nBox 3: 是 -\nYou can create alerts in Azure Monitor.\nAlerts in Azure Monitor proactively notify you of critical conditions and potentially attempt to take corrective action. Alert\nrules based on metrics provide near real time alerting based on numeric values, while rules based on logs allow for complex\nlogic across data from multiple sources.\n參考資料:"
