    "answerTextZh": "Single sign-on is an authentication method that allows users to sign in using one set of credentials to login across\napplications. Single sign-on makes it easier to manage passwords and increases security capabilities.\nAuthorization is the process of establishing what level of access a legitimate user or service should have.\nDuring sign-in, Conditional Access collects signals from the user, makes decisions based on those signals, and then enforces\nthat decision by allowing or denying the access request or challenging for a multifactor authentication response.\n\nthat decision by allowing or denying the access request or challenging for a multifactor authentication response.\n參考資料:"
