    "answerTextZh": "Public Preview means that the service is in public beta and can be tried out by anyone with an Azure 訂用帳戶. Services\nin public preview are often offered at a discount price.\nPublic previews are excluded from SLAs and in some cases, no support is offered.\nIncorrect Answers:\nServices in private preview are available only to selected people who has signed up to the private preview program.\n\n- Services in development are not available to the public.\n- Services provided under an Enterprise Agreement (EA) 訂用帳戶 are available only to the 訂用帳戶 owner.\n參考資料:"
