    "references": [],
    "questionZh": "熱點 -\n要完成句子，請在答案區中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "A stopped (deallocated) VM is offline and not mounted on an Azure host server.\nStarting a VM mounts the VM on a host\nserver before the VM starts.\nAs soon as the VM is mounted, it becomes chargeable.\nFor this reason, you are unable to start a\nVM after a trial has expired.\nIncorrect Answers:\n- You are not charged for Azure Active Directory user accounts so you can continue to create accounts.\n- You can access data that is already stored in Azure.\n- You can access the Azure Portal.\nYou can also reactivate and upgrade the expired 訂用帳戶 in the portal."
