    "options": [],
    "answer": [],
    "answerText": "Box 1: Yes -\nSLA's vary based on the resource type and the location distribution of the resource.\nHowever, the minimum uptime for all\nAzure services is 99.9 percent.\nBox 2: Yes -\nThe SLA guaranteed uptime is increased (usually to 99.95 percent) when resources are deployed across multiple regions.\nBox 3: No -\nThe number of subscriptions is unrelated to uptime SLA's.\nYou can deploy resources to multiple regions under a single\nsubscription or you can have multiple subscriptions with resources deployed to the same region.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n對於以下每個陳述，如果該陳述為真，請選擇「是」。否則，選擇否。\n注意：每個正確的選擇都值得一分。\n熱門區域：",
    "answerTextZh": "Box 1: 是 -\nSLA's vary based on the resource type and the location distribution of the resource.\nHowever, the minimum uptime for all\nAzure services is 99.9 percent.\nBox 2: 是 -\nThe SLA guaranteed uptime is increased (usually to 99.95 percent) when resources are deployed across multiple regions.\nBox 3: 否 -\nThe number of 訂用帳戶s is unrelated to uptime SLA's.\nYou can deploy resources to multiple regions under a single\n訂用帳戶 or you can have multiple 訂用帳戶s with resources deployed to the same region.\n參考資料:"
