    "type": "hotspot",
    "question": "HOTSPOT -\nTo complete the sentence, select the appropriate option in the answer area.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "If the SLA for an Azure service is not met, you receive credits for that service and that service only. The credits are deducted\nfrom your monthly bill for that service.\nIf you stopped using the service where the SLA was not met, your account would remain in credit for that service. The credits\nwould not be applied to any other services that you may be using.\nService Credits apply only to fees paid for the particular Service, Service Resource, or Service tier for which a Service Level\nhas not been met. In cases where\nService Levels apply to individual Service Resources or to separate Service tiers, Service Credits apply only to fees paid for\nthe affected Service Resource or\nService tier, as applicable. The Service Credits awarded in any billing month for a particular Service or Service Resource will\nnot, under any circumstance, exceed your monthly service fees for that Service or Service Resource, as applicable, in the\n\nbilling month.",
    "comments": "",
    "references": [],
    "questionZh": "熱點 -\n要完成句子，請在答案區中選擇適當的選項。\n熱門區域：",
    "answerTextZh": "If the SLA for an Azure service is not met, you receive credits for that service and that service only. The credits are deducted\nfrom your monthly bill for that service.\nIf you stopped using the service where the SLA was not met, your account would remain in credit for that service. The credits\nwould not be applied to any other services that you may be using.\nService Credits apply only to fees paid for the particular Service, Service Resource, or Service tier for which a Service Level\nhas not been met. In cases where\nService Levels apply to individual Service Resources or to separate Service tiers, Service Credits apply only to fees paid for\nthe affected Service Resource or\nService tier, as applicable. The Service Credits awarded in any billing month for a particular Service or Service Resource will\nnot, under any circumstance, exceed your monthly service fees for that Service or Service Resource, as applicable, in the\n\nbilling month.\n參考資料:"
