    "question": "HOTSPOT -\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNOTE: Each correct selection is worth one point.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "Box 1: No -\nAzure Free Account gives you 12 months access to the most popular free services.\nIt also gives you a credit (150 GBP or 200\nUSD) to use on any Azure service for up to 30 days.\nBox 2: Yes -\nAll free accounts expire after 12 months.\nBox 3: No -\nYou can only create one free Azure account per Microsoft account.",
    "comments": "",
