    "options": [],
    "answer": [],
    "answerText": "Public Preview means that the service is in public beta and can be tried out by anyone with an Azure subscription. Services\nin public preview are often offered at a discount price.\nBox 1: No -\nServices in private preview can be viewed in the regular Azure portal.\nHowever, you need to be signed up for the feature in\nprivate preview before you can view it.\nAccess to private preview features is usually by invitation only.\nBox 2: Yes -\nYou can use services in public preview in production environments.\nHowever, you should be aware that the service may have\nfaults, is not subject to an SLA and may be withdrawn without notice.\n\nfaults, is not subject to an SLA and may be withdrawn without notice.\nBox 3: No -\nPublic previews are excluded from SLAs and in some cases, no support is offered.",
