    "question": "HOTSPOT -\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNOTE: Each correct selection is worth one point.\nHot Area:",
    "options": [],
    "answer": [],
    "answerText": "Box 1: No -\nAn Azure free account comes with a 'basic' support plan, not a 'standard' support plan.\nBox 2: Yes -\nYou can purchase the Professional Direct, Standard, and Developer support plans with the Microsoft Customer Agreement.\nYou can also purchase the\nProfessional and Standard support plans with the Enterprise Agreement.\nBox 3: No -\nUsers with any type of Azure subscription (pay-as-you-go, Enterprise Agreement, Microsoft Customer Agreement etc.) can get\nsupport from the MSDN forums.\n\nsupport from the MSDN forums.",
    "comments": "",
